{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows ingress from 0.0.0.0/0 to all ports and protocols, potentially exposing resources to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows egress to 0.0.0.0/0 for all ports and protocols, potentially allowing unrestricted outbound traffic."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"10.0.0.0/8\"]\n  }\n}",
  "fix_summary": "Restricted ingress to only allow HTTPS traffic from 0.0.0.0/0 and limited egress to a private IP range to reduce exposure."
}
